namespace{bool Read(const std::filesystem::path&p,std::string&t){std::ifstream s(p,std::ios::binary);if(!s)return false;t.assign(std::istreambuf_iterator<char>(s),{});return true;}bool S(const std::string&j,const char*k,std::string&v){auto p=j.find(std::string("\"")+k+"\"");if(p==std::string::npos)return false;p=j.find(':',p);p=j.find('"',p);if(p==std::string::npos)return false;++p;v.clear();bool esc=false;for(;p<j.size();++p){char c=j[p];if(esc){if(c=='n')v+='\n';else v+=c;esc=false;}else if(c=='\\')esc=true;else if(c=='"')return true;else v+=c;}return false;}bool N(const std::string&j,const char*k,double&v){auto p=j.find(std::string("\"")+k+"\"");if(p==std::string::npos)return false;p=j.find(':',p);try{v=std::stod(j.substr(p+1));return true;}catch(...){return false;}}}
std::vector<GenerationHistoryEntry> ScanGenerationHistory(const std::filesystem::path&r,std::string&w){w.clear();std::vector<GenerationHistoryEntry>v;std::error_code ec;if(!std::filesystem::exists(r,ec))return v;for(auto&e:std::filesystem::recursive_directory_iterator(r,std::filesystem::directory_options::skip_permission_denied,ec)){if(!e.is_regular_file()||e.path().extension()!=".json")continue;std::string j;if(!Read(e.path(),j))continue;GenerationHistoryEntry x;x.jsonPath=e.path();x.imagePath=e.path();x.imagePath.replace_extension(".png");if(!std::filesystem::is_regular_file(x.imagePath))continue;S(j,"style_name",x.styleName);if(x.styleName.empty())x.styleName=e.path().parent_path().filename().string();S(j,"prompt",x.prompt);S(j,"negative_prompt",x.negativePrompt);S(j,"base_model",x.baseModel);S(j,"lora",x.loraPath);S(j,"generated_time",x.generatedTime);double n;if(N(j,"seed",n))x.seed=(int64_t)n;if(N(j,"lora_strength",n))x.strength=(float)n;if(N(j,"steps",n))x.steps=(int)n;if(N(j,"guidance_scale",n))x.guidance=(float)n;if(N(j,"width",n))x.width=(int)n;if(N(j,"height",n))x.height=(int)n;v.push_back(std::move(x));}std::ranges::sort(v,[](auto&a,auto&b){return a.imagePath>b.imagePath;});return v;}
bool DeleteGenerationHistoryEntry(const GenerationHistoryEntry&e,std::string&error){std::error_code ec;std::filesystem::remove(e.imagePath,ec);if(ec){error="Could not delete image: "+ec.message();return false;}ec.clear();std::filesystem::remove(e.jsonPath,ec);if(ec){error="Image deleted, but JSON could not be deleted: "+ec.message();return false;}return true;}
